import random
import struct
from typing import List

# We generate valid, interesting small files that exercise various InStream paths:
# - Optional UTF-8 BOM
# - Leading blanks (spaces, tabs, CR, LF)
# - Mixture of lines with/without content, including CRLF and LF
# - Tokens separated by single spaces and with non-space characters only
# - Empty file case
# - Short files for char operations
# - Ensure sizes <= 4096 bytes
#
# The fuzzer stubs use FUZZ_PARAM_FILENAME and FUZZ_PARAM_STR, but our buffer
# will be written to files directly by the harness. We should therefore produce
# a plausible text/binary payload that many stubs can use unchanged.

_WHITESPACE_BYTES = b" \t\r\n"


def _rand_ascii_token(rng: random.Random, min_len=1, max_len=32) -> bytes:
    length = rng.randint(min_len, max_len)
    # avoid blanks and line terminators to satisfy token-based reads
    alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._-"
    return bytes(rng.choice(alphabet) for _ in range(length))


def _rand_line(rng: random.Random, max_len=128) -> bytes:
    # Produce a line without internal CR/LF, optionally empty
    if rng.random() < 0.2:
        core = b""
    else:
        # sometimes a single token, sometimes two tokens separated by a single space
        if rng.random() < 0.5:
            core = _rand_ascii_token(rng, 1, rng.randint(1, min(32, max_len)))
        else:
            t1 = _rand_ascii_token(rng, 1, rng.randint(1, min(32, max_len//2)))
            t2 = _rand_ascii_token(rng, 1, rng.randint(1, min(32, max_len//2)))
            core = t1 + b" " + t2
    return core


def _maybe_bom(rng: random.Random) -> bytes:
    return b"\xEF\xBB\xBF" if rng.random() < 0.5 else b""


def _line_ending(rng: random.Random) -> bytes:
    # Mix LF and CRLF
    return b"\r\n" if rng.random() < 0.35 else b"\n"


def _leading_blanks(rng: random.Random) -> bytes:
    # Build a mix of blanks that exercise skipBlanks/seekEof/eoln
    pieces: List[bytes] = []
    # optional spaces/tabs
    if rng.random() < 0.8:
        count = rng.randint(0, 8)
        pieces.append(b" " * count)
        count = rng.randint(0, 4)
        pieces.append(b"\t" * count)
    # optional CR/LF soup
    if rng.random() < 0.6:
        # produce a few CR/LF combos
        for _ in range(rng.randint(0, 2)):
            pieces.append(b"\r")
            if rng.random() < 0.7:
                pieces.append(b"\n")
        # maybe a pure LF block
        pieces.append(b"\n" * rng.randint(0, 3))
    return b"".join(pieces)


def _build_content(rng: random.Random) -> bytes:
    # Choose a scenario to cover different stubs deterministically by seed
    scenario = rng.choice([
        "empty",
        "bom_only",
        "tokens_and_newline",
        "leading_blanks_then_X",
        "multiple_lines",
        "blanks_only",
        "single_newline",
        "short_chars",
    ])

    if scenario == "empty":
        return b""

    if scenario == "bom_only":
        return _maybe_bom(rng)

    if scenario == "tokens_and_newline":
        t1 = _rand_ascii_token(rng, 1, 16)
        t2 = _rand_ascii_token(rng, 1, 16)
        line = t1 + b" " + t2
        return _maybe_bom(rng) + line + _line_ending(rng)

    if scenario == "leading_blanks_then_X":
        return _maybe_bom(rng) + _leading_blanks(rng) + b"X" + _line_ending(rng)

    if scenario == "multiple_lines":
        n = rng.randint(2, 6)
        parts: List[bytes] = [ _maybe_bom(rng) ]
        for i in range(n):
            line = _rand_line(rng, 80)
            parts.append(line + _line_ending(rng))
        return b"".join(parts)

    if scenario == "blanks_only":
        # ensure at least one blank; useful for seekEof/seekEoln
        length = rng.randint(1, 64)
        return bytes(rng.choice(_WHITESPACE_BYTES) for _ in range(length))

    if scenario == "single_newline":
        return _maybe_bom(rng) + _line_ending(rng)

    if scenario == "short_chars":
        # short payload for curChar/nextChar/readChar/unreadChar/skipChar
        payloads = [b"abc", b"Z", b"AB", b"xyz"]
        return rng.choice(payloads)

    return b""


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Optionally prepend a BOM; some stubs explicitly add it, but having it here
    # helps skipBom() path as well.
    content = _build_content(rng)

    # Keep overall size small but occasionally generate a larger multi-line file
    if len(content) < 32 and rng.random() < 0.25:
        # Append a few additional valid lines
        extra_lines = rng.randint(1, 4)
        chunks = [content]
        for _ in range(extra_lines):
            chunks.append(_rand_line(rng, 64) + _line_ending(rng))
        content = b"".join(chunks)

    # Ensure size limit
    if len(content) > 4096:
        content = content[:4096]

    return content
